import { defineConfig } from '@zod-to-form/core';

import type * as Components from '@/components/z2f';
import type * as ZodSchemas from '@/lib/example-schema';

export default defineConfig<typeof Components, typeof ZodSchemas>({
  components: {
    source: '@/components/z2f',
    overrides: {
      Input: {},
      Textarea: {},
      Checkbox: { controlled: true },
      Switch: { controlled: true },
      Select: { controlled: true },
      RadioGroup: { controlled: true },
      DatePicker: { controlled: true }
    }
  },
  defaults: {
    mode: 'submit',
    ui: 'shadcn',
    overwrite: false,
    serverAction: false,
    formProvider: false,
    // optimization: { level: 2 }  // 1 = decompose, 2 = native rules, 3 = cross-field
  },
  include: [],
  exclude: [],
  schemas: {
    schema: {}
  }
});

/**
 * Shared prop shape for controlled shadcn field adapters.
 *
 * z2f codegen binds controlled fields to all five RHF field props
 * (`value onChange onBlur ref name`). `ref` is supplied via React.forwardRef,
 * so it is NOT part of this props object — the remaining four (plus the
 * `disabled`/`id` UI props) are. Adapters must accept a SUPERSET of what
 * codegen emits, otherwise `tsc` fails in a real consumer project.
 */
export type ControlledFieldProps<V = unknown> = {
  value?: V;
  onChange?: (value: V) => void;
  onBlur?: () => void;
  name?: string;
  disabled?: boolean;
  id?: string;
};

/** Owned copy of the option shape (severs the @zod-to-form/core dependency). */
export interface FormFieldOption {
  value: string | number;
  label: string;
  disabled?: boolean;
}

/** Strips index signatures from an inferred Zod type (mirrors codegen's inline util). */
export type StripIndexSignature<T> = T extends Date | File | FileList | Blob | RegExp
  ? T
  : T extends readonly (infer U)[]
    ? StripIndexSignature<U>[]
    : T extends object
      ? {
          [K in keyof T as string extends K
            ? never
            : number extends K
              ? never
              : symbol extends K
                ? never
                : K]: StripIndexSignature<T[K]>;
        }
      : T;

import * as React from 'react';
import {
  Select as ShadcnSelect,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem
} from '@/components/ui/select';
import type { FormFieldOption } from './types';
import type { ControlledFieldProps } from './types';

type Props = ControlledFieldProps<string | number> & {
  placeholder?: string;
  options?: FormFieldOption[];
};

export const Select = React.forwardRef<HTMLButtonElement, Props>(
  ({ value, onChange, onBlur, name, disabled, id, placeholder, options = [] }, ref) => (
    <ShadcnSelect
      value={value == null ? undefined : String(value)}
      onValueChange={(v) => {
        if (v != null) onChange?.(v);
      }}
      disabled={disabled}
    >
      <SelectTrigger ref={ref} id={id} name={name} onBlur={onBlur}>
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        {options.map((o) => (
          <SelectItem key={String(o.value)} value={String(o.value)} disabled={o.disabled}>
            {o.label}
          </SelectItem>
        ))}
      </SelectContent>
    </ShadcnSelect>
  )
);
Select.displayName = 'Select';

import * as React from 'react';
import { RadioGroup as ShadcnRadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Label } from '@/components/ui/label';
import type { FormFieldOption } from './types';
import type { ControlledFieldProps } from './types';

type Props = ControlledFieldProps<string | number> & {
  options?: FormFieldOption[];
};

export const RadioGroup = React.forwardRef<HTMLDivElement, Props>(
  ({ value, onChange, onBlur, name, disabled, options = [] }, ref) => (
    <ShadcnRadioGroup
      ref={ref}
      name={name}
      onBlur={onBlur}
      value={value == null ? undefined : String(value)}
      onValueChange={(v) => onChange?.(v)}
      disabled={disabled}
    >
      {options.map((o, index) => {
        const itemId = `${name ?? 'radio'}-${index}`;
        return (
          <div key={String(o.value)}>
            <RadioGroupItem value={String(o.value)} id={itemId} disabled={o.disabled} />
            <Label htmlFor={itemId}>{o.label}</Label>
          </div>
        );
      })}
    </ShadcnRadioGroup>
  )
);
RadioGroup.displayName = 'RadioGroup';

import * as React from 'react';
import { format } from 'date-fns';
import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverTrigger, PopoverContent } from '@/components/ui/popover';
import type { ControlledFieldProps } from './types';

export const DatePicker = React.forwardRef<
  HTMLButtonElement,
  ControlledFieldProps<Date | undefined>
>(({ value, onChange, name, disabled, id }, ref) => {
  const selected = value instanceof Date && !Number.isNaN(value.getTime()) ? value : undefined;
  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button
            ref={ref}
            type="button"
            variant="outline"
            id={id}
            name={name}
            disabled={disabled}
          />
        }
      >
        {selected ? format(selected, 'PPP') : 'Pick a date'}
      </PopoverTrigger>
      <PopoverContent>
        <Calendar mode="single" selected={selected} onSelect={(d?: Date) => onChange?.(d)} />
      </PopoverContent>
    </Popover>
  );
});
DatePicker.displayName = 'DatePicker';

/**
 * Aggregated exports for the shadcn zod-form adapter module.
 * Input/Textarea/Checkbox/Switch are thin re-exports of raw shadcn ui/* primitives.
 * Select/RadioGroup/DatePicker are local wrappers that normalize complex bindings.
 * Field* layout primitives come from @/components/ui/field (Base UI, Oct 2025).
 */
export { Input } from '@/components/ui/input';
export { Textarea } from '@/components/ui/textarea';
export { Checkbox } from '@/components/ui/checkbox';
export { Switch } from '@/components/ui/switch';
export { Select } from './select';
export { RadioGroup } from './radio-group';
export { DatePicker } from './date-picker';

// Re-export the Base UI Field* layout primitives so codegen/?z2f-generated forms
// can import BOTH the field components AND the field-template wrappers from the
// single `@/components/z2f` module. These are template wrappers, NOT field
// components — they are deliberately absent from the `components` map below.
export { Field, FieldLabel, FieldDescription, FieldError, FieldGroup } from '@/components/ui/field';

export type { StripIndexSignature, FormFieldOption, ControlledFieldProps } from './types';

import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Checkbox } from '@/components/ui/checkbox';
import { Switch } from '@/components/ui/switch';
import { Select } from './select';
import { RadioGroup } from './radio-group';
import { DatePicker } from './date-picker';

export const components = {
  Input,
  Textarea,
  Checkbox,
  Switch,
  Select,
  RadioGroup,
  DatePicker
};

import { useForm, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Checkbox, DatePicker, Field, FieldError, FieldLabel, Input, Select } from '@/components/z2f';
import type { StripIndexSignature } from '@/components/z2f';
import { schema } from '@/lib/example-schema';

type FormData = StripIndexSignature<z.input<typeof schema>>;
type FormOutput = StripIndexSignature<z.output<typeof schema>>;

const _resolver = zodResolver(schema);

export function GeneratedForm(props: {
  onSubmit: (data: FormOutput) => void;
  defaultValues?: Partial<FormData>;
  values?: FormData;
  fieldProps?: Record<string, Record<string, unknown>>;
}) {
  const form = useForm<FormData>({
    resolver: _resolver,
    defaultValues: props.defaultValues,
    values: props.values,
  });
  const { register, handleSubmit, control } = form;

  return (
    <form onSubmit={handleSubmit((data) => props.onSubmit(data as unknown as FormOutput))}>
      <Field>
        <FieldLabel htmlFor="name">Name</FieldLabel>
        <Input id="name" required type="text" minLength={2} {...register('name')} {...(props.fieldProps?.["name"] ?? {})} />
        <FieldError>{form.getFieldState("name", form.formState).error?.message}</FieldError>
      </Field>
      <Field>
        <FieldLabel htmlFor="email">Email</FieldLabel>
        <Input id="email" required type="email" pattern="^(?!\.)(?!.*\.\.)([A-Za-z0-9_'+\-\.]*)[A-Za-z0-9_+-]@([A-Za-z0-9][A-Za-z0-9\-]*\.)+[A-Za-z]{2,}$" {...register('email')} {...(props.fieldProps?.["email"] ?? {})} />
        <FieldError>{form.getFieldState("email", form.formState).error?.message}</FieldError>
      </Field>
      <Field>
        <FieldLabel htmlFor="age">Age</FieldLabel>
        <Input id="age" type="number" min={18} {...register('age', { setValueAs: (v: unknown) => (v === '' || v == null ? undefined : Number(v)) })} {...(props.fieldProps?.["age"] ?? {})} />
        <FieldError>{form.getFieldState("age", form.formState).error?.message}</FieldError>
      </Field>
      <Field>
        <FieldLabel htmlFor="subscribe">Subscribe to updates</FieldLabel>
        <Controller name={"subscribe"} control={control} render={({ field }) => (
  <Checkbox id="subscribe" value={field.value} onBlur={field.onBlur} ref={field.ref} name={field.name} checked={!!field.value} onCheckedChange={field.onChange} {...(props.fieldProps?.["subscribe"] ?? {})} />
)} />
        <FieldError>{form.getFieldState("subscribe", form.formState).error?.message}</FieldError>
      </Field>
      <Field>
        <FieldLabel htmlFor="role">Role</FieldLabel>
        <Controller name={"role"} control={control} render={({ field }) => (
  <Select id="role" value={field.value} onChange={field.onChange} onBlur={field.onBlur} ref={field.ref} name={field.name} {...(props.fieldProps?.["role"] ?? {})} />
)} />
        <FieldError>{form.getFieldState("role", form.formState).error?.message}</FieldError>
      </Field>
      <Field>
        <FieldLabel htmlFor="birthDate">Birth date</FieldLabel>
        <Input id="birthDate" type="date" pattern="^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))$" {...register('birthDate')} {...(props.fieldProps?.["birthDate"] ?? {})} />
        <FieldError>{form.getFieldState("birthDate", form.formState).error?.message}</FieldError>
      </Field>
      <Field>
        <FieldLabel htmlFor="joinedAt">Joined</FieldLabel>
        <Controller name={"joinedAt"} control={control} render={({ field }) => (
  <DatePicker id="joinedAt" value={field.value} onChange={field.onChange} onBlur={field.onBlur} ref={field.ref} name={field.name} {...(props.fieldProps?.["joinedAt"] ?? {})} />
)} />
        <FieldError>{form.getFieldState("joinedAt", form.formState).error?.message}</FieldError>
      </Field>
      <button type="submit">Submit</button>
    </form>
  );
}

export default GeneratedForm;
